#pragma once

#include "psprecomp/runtime.hpp"

#include <cstdint>
#include <string>

namespace spongebob {

// Load the phase-2 symbol map (analysis/symbols/symbols.csv, generated by
// tools/symbolize) plus the analyzer's function list, and install a runtime
// symbolizer so crash dumps and traces print names. PSPRECOMP_SYMBOLS=<csv>
// overrides the path; PSPRECOMP_SYMBOLS=0 disables it. Missing files are fine.
void install_symbols(psprecomp::Runtime &runtime);

// "Class::Method", "Class::Method+0x1C", "sub_0888EA9C+0x8" or "" if unknown.
[[nodiscard]] std::string symbol_for(std::uint32_t address);

}  // namespace spongebob
